const jsonServer = require('json-server')
const server = jsonServer.create()
const router = jsonServer.router('json-server/db.json')
const middlewares = jsonServer.defaults()
let userCurrentapi = 0;
let datasetCurrentapi = 0;
server.use(middlewares)
server.use(jsonServer.rewriter({
  '/session/*': '/$1',
  '/event/*': '/$1',
  '/menu/*': '/$1',
  '/collection/root': '/root',
  '/collection/*\\?tree=:tree': '/$1',
  "/collection/root/items\\?models=:models": "/rootitems",
  '/user/*': '/$1',
  '/automagic-dashboards/table/3/query_metadata': '/query_metadata',
  '/automagic-dashboards/table/3': '/3'

}))
server.use((req, res, next) => {
  if(res.req.url=='/current' &&userCurrentapi==0) {
    userCurrentapi++;
    res.status(500).jsonp({
      error: "error message here"
    })
  }
  if (req.method === "POST") {
    // If the method is a POST echo back the name from request body
    if(req.originalUrl==="/dataset") {
      datasetCurrentapi++;
      switch (datasetCurrentapi) {
        case 1:
          res.json(dataset1);
          break;
        case 2:
          res.json(dataset2);
          break;
        case 3:
          res.json(dataset3);
          break;
        case 4:
          res.json(dataset4);
          break;
        case 5:
          res.json(dataset5);
          break;
        case 6:
          res.json(dataset6);
          break;
        case 7:
          res.json(dataset7);
          break;
        default:
          res.json(dataset8);
          datasetCurrentapi=0;
      }
    }
    else {
      res.json({"id":"190d3afd-e2ab-448d-9320-1f6a6292aa7e"});
    }
  } else {
    //Not a post request. Let db.json handle it
    next();
 }
})
server.use(router)
server.listen(3001, () => {
  console.log('JSON Server is running')
})




